$allItems = [];
$page = 1;
while (true) {
    $result = $tools->call('publishing_list', ['page' => $page]);
    if (!isset($result->items) || !is_array($result->items)) {
        break; // unexpected
    }
    foreach ($result->items as $item) {
        $allItems[] = $item;
    }
    if (!property_exists($result, 'nextPage') || $result->nextPage === null) {
        break;
    }
    $page = $result->nextPage;
}
$audited = count($allItems);
$missing = [];
foreach ($allItems as $item) {
    // meta_description may be empty string or whitespace; treat empty after trim as missing
    if (!isset($item->meta_description) || trim($item->meta_description) === '') {
        $missing[] = $item->id;
    }
}
sort($missing, SORT_NUMERIC);
return ['audited' => $audited, 'missing' => $missing];

